def sprite():
    syms = "".join(f'<symbol id="i-{k}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round">{v}</symbol>' for k, v in ICONS.items())
    syms += "".join(f'<symbol id="i-{k}" viewBox="0 0 24 24" fill="currentColor">{v}</symbol>' for k, v in FILLED.items())
    return f'<svg width="0" height="0" style="position:absolute" aria-hidden="true">{syms}</svg>'


def ic(name, cls="icon"):
    return f'<svg class="{cls}" aria-hidden="true" focusable="false"><use href="#i-{name}"></use></svg>'
